const SF_LIVABLE_NOTE = 'Catalog design placed inside the R-4 setback envelope (south_parcel_concept.py)';
const TH_LIVABLE_NOTE = "Two-story 31' × 38' townhome unit, ~1,900 SF livable (south_parcel_concept.py)";

/** Main-project defaults, re-pointed at the South Parcel (unit costs stay in sync with the main proforma). */
export function buildSouthDefaults(mainDefaults) {
  const overrides = {
    land_cost_total: LAND_ALLOCATION,
    initial_equity: STARTING_CASH,
  };
  const assumptions = mainDefaults.assumptions.map((entry) => {
    const o = overrides[entry.id];
    if (!o) return { ...entry };
    return {
      ...entry,
      value: o.value,
      default: o.value,
      description: o.description ?? entry.description,
      source: o.source ?? entry.source,
    };
  });
  const known = new Set(assumptions.map((a) => a.id));
  EXTRA_ASSUMPTIONS.forEach((extra) => {
    if (!known.has(extra.id)) assumptions.push({ ...extra });
  });
  const { transfers, platAreas, ...rest } = mainDefaults;
  return {
    ...rest,
    description:
      'South Parcel for-sale proforma. Lots, streets and quantities come from the code-checked concept layouts; unit costs match the main Delta Crossings proforma.',
    phaseOrder: [1],
    ordinanceRef: {
      title: "Delta City ST-02 60' local road (Ord. 2025-317)",
      path: 'Supporting Docs/City Ordinances/1760410617_Ordinance 2025-317 Construction Standards.pdf',
      drawings: ["ST-02 60' local road: 41' asphalt, 2.5' curb & gutter, 5' sidewalk each side"],
    },
    assumptions,
  };
}

function lotNumberFor(lotId, unitIndex = 0) {
  return Number(lotId) * 10 + unitIndex;
}

/** Turn one concept from concepts.json into the site model computeProforma expects. */
export function buildSiteModel(data, conceptId) {
  const concept = data.concepts.find((c) => c.id === conceptId) || data.concepts[0];
  const homes = [];
  const pushSingleFamily = (lot) => {
    homes.push({
      lotNumber: lotNumberFor(lot.id),
      label: lot.id,
      lotType: 'single-family',
      phase: 1,
      squareFeet: lot.areaSqFt,
      dwellingSqFt: lot.livableSqFt,
      dwellingSource: `${SF_LIVABLE_NOTE}: ${lot.design}`,
    });
  };
  data.base.existingLots.forEach(pushSingleFamily);
  concept.lots.forEach((lot) => {
    if (lot.type === 'SF') {
      pushSingleFamily(lot);
      return;
    }
    const perUnit = lot.livableSqFt / Math.max(lot.units, 1);
    lot.unitLots.forEach((unit, index) => {
      homes.push({
        lotNumber: lotNumberFor(lot.id, index + 1),
        label: `${lot.id}-${unit.id}`,
        lotType: 'townhome',
        phase: 1,
        squareFeet: unit.areaSqFt,
        dwellingSqFt: perUnit,
        dwellingSource: TH_LIVABLE_NOTE,
      });
    });
  });

  const q = concept.quantities;
  const storm = concept.stormwater;
  const takeoff = {
    sectionRef: 'ST-02',
    source: `Concept ${concept.id} takeoff from scripts/south_parcel_concept.py`,
    centerlineLf: q.newStreetCenterlineFt + q.harvestLaneCenterlineFt,
    rowSqFt: q.newStreetRowSqFt + q.harvestLaneRowSqFt,
    asphaltSqFt: q.asphaltSqFt,
    curbGutterLf: q.curbGutterLf,
    sidewalkSqFt: q.sidewalkSqFt,
    waterMainLf: q.waterMainLf,
    sewerMainLf: q.sewerMainLf,
    stormDrainLf: q.stormDrainLf,
    dryUtilityTrenchLf: q.dryUtilityTrenchLf,
    sewerManholes: q.sewerManholes,
    stormManholes: q.stormManholes,
    streetLights: q.streetLights,
    stormStorageCf: storm.requiredVolumeCf,
    stormStorageCy: storm.requiredVolumeCf / 27,
    ditchPipeLf: q.ditchPipeLf,
    segments: [
      {
        id: 'street-ab',
        lengthFt: q.newStreetCenterlineFt,
        orientation: 'east-west, then north',
        label: "Street A/B (new, 60' ROW)",
      },
      {
        id: 'harvest-lane',
        lengthFt: q.harvestLaneCenterlineFt,
        orientation: 'north-south',
        label: 'Harvest Lane south of Jasper (moved from main proforma)',
      },
    ],
    notes: q.notes.join(' '),
  };

  return {
    name: `South Parcel — Concept ${concept.id}: ${concept.name}`,
    concept,
    homes,
    takeoff,
    softCosts: SOFT_COSTS,
  };
}

export async function fetchJson(relativePath, label) {
  const response = await fetch(platUrl(relativePath));
  if (!response.ok) throw new Error(`${label} failed (${response.status})`);
  const text = await response.text();
  if (text.trimStart().startsWith('<')) {
    throw new Error(`${label} returned HTML instead of JSON. Use the Vite dev server (npm run dev in web-3d).`);
  }
  return JSON.parse(text);
}

export function loadConcepts() {
  return fetchJson(`${CONCEPTS_URL}?v=1`, 'South parcel concepts');
}

export function readInitialConcept() {
  try {
    const fromUrl = new URLSearchParams(window.location.search).get(CONCEPT_PARAM);
    if (CONCEPT_OPTIONS.some((c) => c.id === fromUrl)) return fromUrl;
    const stored = localStorage.getItem(CONCEPT_STORAGE_KEY);
    if (CONCEPT_OPTIONS.some((c) => c.id === stored)) return stored;
  } catch {
    /* ignore storage errors */
  }
  return 'B';
}

export function rememberConcept(conceptId) {
  try {
    localStorage.setItem(CONCEPT_STORAGE_KEY, conceptId);
    const url = new URL(window.location.href);
    url.searchParams.set(CONCEPT_PARAM, conceptId);
    window.history.replaceState({}, '', `${url.pathname}${url.search}${url.hash}`);
  } catch {
    /* ignore storage errors */
  }
}
